package com.example.starter.api.dto;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotNull;

/**
 * 高度带配置项（左闭右开，单位米）。
 *
 * @param bandLower 高度带下限（含），米
 * @param bandUpper 高度带上限（不含），米，bandLower &lt; bandUpper
 * @param capacity  同时容量，1~50；修改时只能上调
 */
public record BandSpecDto(
        @NotNull Integer bandLower,
        @NotNull Integer bandUpper,
        @NotNull @Min(1) @Max(50) Integer capacity) {
}

package com.example.starter.api.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 区域高度带配置修改请求。只允许：上调既有高度带容量、新增与既有带不重叠的带；
 * 不允许下调容量、删除带或修改带边界。携带区域 expectedVersion 做乐观锁，
 * 冲突返回 409。修改不追溯改写已有占用记录，但会推进空域版本使旧审查变为 STALE。
 *
 * @param zoneId          区域唯一标识
 * @param expectedVersion 期望的区域高度带配置版本
 * @param bands           修改后的完整高度带配置（既有带不得缺失，边界不得改变）
 * @param requestId       写操作全局唯一请求标识，用于幂等重放
 */
public record BandConfigRequest(
        @NotBlank @Size(max = 64) String zoneId,
        @NotNull Integer expectedVersion,
        @NotNull @Valid @Size(min = 1, max = 50) List<BandSpecDto> bands,
        @NotBlank @Size(max = 64) String requestId) {
}

package com.example.starter.api.dto;

import java.util.List;

/**
 * 区域高度带配置结果。
 *
 * @param zoneId       区域标识
 * @param zoneVersion  修改成功后的区域配置版本（每次修改加一）
 * @param bands        当前完整高度带配置（按下限升序）
 */
