            assertEquals(n - 1, replayCount);
            assertEquals(1, jdbc.queryForObject(
                    "SELECT COUNT(*) FROM altitude_occupancy WHERE status='ACTIVE'",
                    Integer.class));
            assertEquals(1, jdbc.queryForObject(
                    "SELECT COUNT(*) FROM request_dedup WHERE request_id=?",
                    Integer.class, requestId));
        } finally {
            pool.shutdownNow();
        }
    }
}

